function cuts2fit = fit_bg_helper(source_ds,cut1_proj,cut2_proj,bg_range,cuts2fit,a2,field_name,all_range)
ds1 = IX_dataset_1d(cut(source_ds,cut1_proj,bg_range,all_range{1:2},[50,4,360],'-nopix'));
ds2 = IX_dataset_1d(cut(source_ds,cut2_proj,bg_range,all_range{1:2},[50,4,360],'-nopix'));
ds1 = log(ds1);ds1.signal = real(ds1.signal);
ds2 = log(ds2);ds2.signal = real(ds2.signal);
acolor k
plot(ds1);liny; pd(ds2);
fc = multifit(ds1,ds2);
fc = fc.set_fun(@double_exp1Dlog);
fc = fc.set_pin([ds1.signal(1),0,a2,0]);
fc = fc.set_free([1,1,1,1]);
[fd,fp] = fc.fit();
acolor g
pl(fd{1});
acolor b
pl(fd{2});keep_figure;
fp.p(3) = abs(fp.p(3));
cuts2fit.(field_name) = fp;

w1t= cut(source_ds,cut1_proj,bg_range,all_range{:},'-nopix');
plot(w1t);logy;
tf = func_eval(w1t,@double_exp1D,fp.p);
acolor r
pd(tf); keep_figure

end

